// scripts/lib/generateContent.mjs (WP0): computes every generated file from the TypeScript sources and prints
// {"files": {"<repo-relative path>": "<content>"}} on stdout. Run by scripts/generate.mjs as
//   node --experimental-transform-types --import ./scripts/lib/tsHooks.mjs scripts/lib/generateContent.mjs
// It never writes files; generate.mjs formats, compares and writes. Nothing else may print to stdout here.
import { readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { Client } from "@modelcontextprotocol/client";
import { InMemoryTransport } from "@modelcontextprotocol/server";
import { z } from "zod";

import { measureTool, sortedJson } from "./catalogMetrics.mjs";

const src = (rel) => new URL(`../../src/${rel}`, import.meta.url).href;
const { TOOL_CONTRACTS } = await import(src("contracts/index.ts"));
const { TOOL_AREAS, isCommandTier, kebab } = await import(src("contracts/toolContract.ts"));
const { effectFlags } = await import(src("contracts/effects.ts"));
const { createApplication } = await import(src("application/createApplication.ts"));
const { notImplementedPort } = await import(src("application/notImplemented.ts"));
const { createHandleRegistry } = await import(src("application/handles/createHandleRegistry.ts"));
const { loadConfig } = await import(src("domain/config.ts"));
const { silentLogger } = await import(src("domain/logger.ts"));
const { sha256Hex } = await import(src("domain/canonical.ts"));
const { BEA_ERROR_TAGS } = await import(src("domain/errors/beaError.ts"));
const { BEA_ERROR_CODES, BEA_ERROR_CATEGORIES, ERROR_CATALOG } = await import(src("domain/errors/errorCatalog.ts"));
const { ERROR_SAMPLES } = await import(src("domain/errors/errorSamples.fixture.ts"));
const { beaErrorEnvelopeSchema, projectBeaError } = await import(src("domain/errors/projection.ts"));
const { createMcpServer } = await import(src("server/createMcpServer.ts"));
const { Delivery } = await import(src("server/delivery.ts"));

const repoRoot = new URL("../../", import.meta.url);
const GENERATED_NOTE =
  "GENERATED by scripts/generate.mjs. Do not edit; run `npm run generate` (drift fails `npm run check`).";

/** Area -> owning work package (DESIGN §3, D-INT-5). */
const AREA_OWNERS = {
  sessions: "WP4-SESS",
  inspect: "WP6-INSPECT",
  address: "WP5-ADDR",
  scan: "WP10-SCAN",
  instrument: "WP7-HOOK",
  behavior: "WP8-BEHAV",
  watch: "WP9-WATCH",
  call: "WP11-CALL",
  modify: "WP12-MODIFY",
  dump: "WP13-DUMP",
  emulation: "WP14-EMU",
  evidence: "WP1-EVID",
};
const AREA_TITLES = {
  sessions: "Sessions, discovery and lifecycle",
  inspect: "Inspection",
  address: "Address mapping and symbols",
  scan: "Memory scanning",
  instrument: "Instruments and recordings",
  behavior: "API behavior profiles",
  watch: "Watchpoints, tracing and coverage",
  call: "In-process calls",
  modify: "Gated modification",
  dump: "Dumps",
  emulation: "Emulation and differential testing",
  evidence: "Evidence and unknowns",
};

// ---------------------------------------------------------------- tools/list exactly as clients see it
async function advertisedTools() {
  const home = join(tmpdir(), "bea-generate-home-never-written");
  const loaded = await loadConfig({
    env: { BEA_HOME: home },
    platform: process.platform,
    accountHome: tmpdir(),
    readConfigFile: async () => null,
  });
  if (!loaded.ok) throw new Error(`generate: config failed: ${JSON.stringify(loaded.error)}`);
  const app = await createApplication({
    config: loaded.value,
    logger: silentLogger,
    transport: "cli",
    services: async () => ({
      evidence: notImplementedPort("evidence"),
      jobhost: notImplementedPort("jobhost"),
      pe: { images: notImplementedPort("pe.images"), hashes: notImplementedPort("pe.hashes") },
      address: notImplementedPort("address"),
      recordings: notImplementedPort("recordings"),
      sessions: notImplementedPort("sessions"),
      handles: createHandleRegistry(),
      oracle: notImplementedPort("oracle"),
      dumps: notImplementedPort("dumps"),
      emulator: notImplementedPort("emulator"),
    }),
  });
  const server = createMcpServer({
    core: app,
    handlers: () => undefined,
    contracts: TOOL_CONTRACTS,
    delivery: new Delivery(10 * 1024 * 1024),
  });
  const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
  await server.connect(serverTransport);
  const client = new Client({ name: "bea-generate", version: "1" });
  await client.connect(clientTransport);
  try {
    return (await client.listTools()).tools;
  } finally {
    await client.close();
    await server.close();
  }
}

// ---------------------------------------------------------------- per-area catalog slices
const sliceRow = (contract, tool) => {
  const measure = measureTool(tool);
  return {
    name: contract.name,
    title: contract.title,
    phase: contract.phase,
    description_chars: measure.description_chars,
    effects: effectFlags(contract.effects),
    annotations: contract.annotations,
    gate: contract.gate,
    cli: contract.cli,
    session_kinds: contract.sessionKinds,
    evidence: contract.evidence,
    errors: contract.errors,
    returns_target_content: contract.returnsTargetContent,
    max_blocking_ms: contract.maxBlockingMs,
    max_input_bytes: contract.maxInputBytes,
    examples: contract.examples.length,
    input_schema_bytes: measure.input_bytes,
    output_schema_bytes: measure.output_bytes,
    model_visible_bytes: measure.model_visible_bytes,
    input_depth: measure.input_depth,
    output_depth: measure.output_depth,
    input_schema: tool.inputSchema,
    output_schema_sha256: sha256Hex(sortedJson(tool.outputSchema ?? null)),
  };
};

// ---------------------------------------------------------------- markdown helpers
const cell = (text) => String(text).replaceAll("\\", "\\\\").replaceAll("|", "\\|").replaceAll("\n", " ");
const code = (text) => `\`${String(text).replaceAll("`", "'")}\``;

// Union members are joined with a plain "|": cell() escapes it once for the table (joining with an already escaped
// "\|" made cell() escape it again, and the pages showed a literal backslash before every "|").
const typeOf = (schema) => {
  if (schema === undefined || schema === null || typeof schema !== "object") return "any";
  if (Array.isArray(schema.enum)) {
    const values = schema.enum.map((v) => JSON.stringify(v));
    return values.length <= 8 ? values.join(" | ") : `${values.slice(0, 8).join(" | ")} | …`;
  }
  if (schema.const !== undefined) return JSON.stringify(schema.const);
  for (const key of ["anyOf", "oneOf"]) if (Array.isArray(schema[key])) return schema[key].map(typeOf).join(" | ");
  const type = Array.isArray(schema.type) ? schema.type.join("|") : schema.type;
  if (type === "integer" || type === "number") {
    const lo = schema.minimum ?? schema.exclusiveMinimum;
    const hi = schema.maximum ?? schema.exclusiveMaximum;
    return lo === undefined && hi === undefined ? type : `${type} ${lo ?? "−∞"}..${hi ?? "∞"}`;
  }
  if (type === "string") {
    const bounds = schema.maxLength === undefined ? "" : ` ≤${schema.maxLength}`;
    return schema.pattern === undefined ? `string${bounds}` : `string${bounds} ${code(schema.pattern)}`;
  }
  if (type === "array")
    return `array<${typeOf(schema.items)}>${schema.maxItems === undefined ? "" : ` ≤${schema.maxItems}`}`;
  return type ?? "any";
};

const toolMarkdown = (contract, tool) => {
  const a = contract.annotations;
  const hints = [
    a.readOnlyHint ? "read-only" : null,
    a.destructiveHint ? "destructive" : null,
    a.idempotentHint ? "idempotent" : null,
    a.openWorldHint ? "open-world" : null,
  ].filter((h) => h !== null);
  const effects = effectFlags(contract.effects);
  const cli = isCommandTier(contract.cli)
    ? code(`bea ${contract.cli.command}${contract.cli.positional.map((p) => ` <${p}>`).join("")}`) +
      ` (${contract.cli.tier})`
    : `${contract.cli.tier}: ${contract.cli.reason}`;
  const gate = contract.gate === null ? "—" : `${code(contract.gate.id)} (${contract.gate.scope})`;
  const lines = [
    `## ${code(contract.name)} — ${contract.title}`,
    "",
    contract.description,
    "",
    "| Phase | Hints | Effects | Gate | CLI |",
    "| --- | --- | --- | --- | --- |",
    `| ${contract.phase} | ${cell(hints.join(", ") || "—")} | ${cell(effects.join(", ") || "—")} | ${cell(gate)} | ${cell(cli)} |`,
    "",
  ];
  const properties = Object.entries(tool.inputSchema?.properties ?? {});
  if (properties.length === 0) lines.push("Input: no fields.", "");
  else {
    const required = new Set(tool.inputSchema.required ?? []);
    lines.push("| Input field | Type | Required | Default | Description |", "| --- | --- | --- | --- | --- |");
    for (const [field, schema] of properties)
      lines.push(
        `| ${code(field)} | ${cell(typeOf(schema))} | ${required.has(field) ? "yes" : "no"} | ` +
          `${schema.default === undefined ? "—" : code(JSON.stringify(schema.default))} | ${cell(schema.description ?? "")} |`,
      );
    lines.push("");
  }
  const recorded =
    contract.evidence.recorded === "never"
      ? "not recorded"
      : `${contract.evidence.recorded} as ${code(contract.evidence.predicate)}`;
  lines.push(
    `Deadline ${contract.maxBlockingMs.toLocaleString("en-US")} ms · input ≤ ${contract.maxInputBytes.toLocaleString("en-US")} bytes · ` +
      `evidence ${recorded} · sessions ${contract.sessionKinds.join(", ")} · ` +
      `${contract.returnsTargetContent ? "results carry untrusted target content" : "results carry no target content"}.`,
    "",
  );
  return lines.join("\n");
};

const areaMarkdown = (area, rows) => {
  const owner = AREA_OWNERS[area];
  const head = [
    `# ${AREA_TITLES[area]} (\`${area}\`)`,
    "",
    `<!-- ${GENERATED_NOTE} -->`,
    "",
    `Area \`${area}\` is owned by ${owner}; its contracts live in \`src/contracts/areas/${area}.ts\`.`,
    "",
  ];
  if (rows.length === 0) return [...head, "No tools yet.", ""].join("\n");
  return [...head, ...rows.map(({ contract, tool }) => toolMarkdown(contract, tool))].join("\n");
};

// ---------------------------------------------------------------- errors
const errorsMarkdown = () => {
  const tagsByCode = new Map(BEA_ERROR_CODES.map((c) => [c, []]));
  for (const tag of BEA_ERROR_TAGS) tagsByCode.get(ERROR_CATALOG[tag].code)?.push(tag);
  const lines = [
    "# BEA error contract",
    "",
    `<!-- ${GENERATED_NOTE} -->`,
    "",
    'Every failed tool call returns `isError: true` with one text item whose content is `{"error": projection}` and no',
    "`structuredContent`. The projection is closed: the codes and categories below are the only ones BEA emits. JSON",
    "Schema: [error-contract.schema.json](error-contract.schema.json). `details.effects_applied` is always present and",
    "lists target changes made before the failure.",
    "",
    "## Codes",
    "",
    "| Code | Category | Error tags |",
    "| --- | --- | --- |",
  ];
  for (const codeName of BEA_ERROR_CODES) {
    const tags = tagsByCode.get(codeName) ?? [];
    const category =
      codeName === "cleanup_incomplete" ? "execution_failure" : (ERROR_CATALOG[tags[0] ?? "Internal"]?.category ?? "");
    lines.push(
      `| ${code(codeName)} | ${code(category)} | ${tags.length === 0 ? "projection override when cleanup is incomplete" : tags.map(code).join(", ")} |`,
    );
  }
  lines.push("", `Categories: ${BEA_ERROR_CATEGORIES.map(code).join(", ")}.`, "", "## One example per tag", "");
  for (const tag of BEA_ERROR_TAGS) {
    const projected = projectBeaError(ERROR_SAMPLES[tag]);
    lines.push(
      `### ${code(tag)} → ${code(projected.code)}`,
      "",
      "```json",
      JSON.stringify({ error: projected }, null, 2),
      "```",
      "",
    );
  }
  return lines.join("\n");
};

// ---------------------------------------------------------------- assemble
const pkg = JSON.parse(await readFile(new URL("package.json", repoRoot), "utf8"));
const files = {};
files["src/generated/packageMetadata.ts"] = [
  "// GENERATED by scripts/generate.mjs from package.json. Do not edit. `npm run check` fails on drift.",
  "export const PACKAGE_METADATA = {",
  `  name: ${JSON.stringify(pkg.name)},`,
  `  version: ${JSON.stringify(pkg.version)},`,
  `  skillVersion: ${JSON.stringify(pkg.bea?.skillVersion ?? "1")},`,
  "} as const;",
  "",
].join("\n");

const tools = await advertisedTools();
const byName = new Map(tools.map((tool) => [tool.name, tool]));
const index = [];
for (const area of TOOL_AREAS) {
  const rows = TOOL_CONTRACTS.filter((c) => c.area === area).map((contract) => {
    const tool = byName.get(contract.name);
    if (tool === undefined) throw new Error(`generate: tools/list is missing ${contract.name}`);
    return { contract, tool };
  });
  const slice = {
    schema: "bea.catalog-slice/1",
    note: GENERATED_NOTE,
    area,
    owner: AREA_OWNERS[area],
    tools: rows.map(({ contract, tool }) => sliceRow(contract, tool)),
  };
  files[`tests/golden/catalog/${area}.json`] = `${JSON.stringify(slice, null, 2)}\n`;
  files[`docs/tools/${area}.md`] = areaMarkdown(area, rows);
  index.push({
    area,
    owner: AREA_OWNERS[area],
    slice: `catalog/${area}.json`,
    docs: `docs/tools/${area}.md`,
    tools: rows.map(({ contract }) => contract.name),
    // Digest of the slice DATA (key-sorted JSON), so it does not depend on formatting.
    sha256: sha256Hex(sortedJson(slice)),
  });
}
files["tests/golden/catalog.json"] = `${JSON.stringify(
  { schema: "bea.catalog-index/1", note: GENERATED_NOTE, tool_count: TOOL_CONTRACTS.length, areas: index },
  null,
  2,
)}\n`;
files["docs/tools.md"] = [
  "# BEA tools",
  "",
  `<!-- ${GENERATED_NOTE} -->`,
  "",
  `${TOOL_CONTRACTS.length} tool(s) in ${TOOL_AREAS.length} areas, in \`tools/list\` order. Each area has its own generated`,
  "page and golden slice (`tests/golden/catalog/<area>.json`), owned by the area's work package; regenerate with",
  "`npm run generate`, never edit or hand-merge them.",
  "",
  "| Area | Owner | Tools | Page | Slice sha256 |",
  "| --- | --- | --- | --- | --- |",
  ...index.map(
    (entry) =>
      `| ${code(entry.area)} | ${entry.owner} | ${entry.tools.length === 0 ? "—" : entry.tools.map(code).join(", ")} | ` +
      `[tools/${entry.area}.md](tools/${entry.area}.md) | ${code(entry.sha256.slice(0, 16))} |`,
  ),
  "",
  "CLI commands: " +
    (TOOL_CONTRACTS.filter((c) => isCommandTier(c.cli))
      .map((c) => code(`bea ${c.cli.command}`))
      .join(", ") || "none") +
    `. Tools without a command: ${
      TOOL_CONTRACTS.filter((c) => !isCommandTier(c.cli))
        .map((c) => code(kebab(c.name)))
        .join(", ") || "none"
    }.`,
  "",
].join("\n");
files["docs/errors.md"] = errorsMarkdown();
files["docs/error-contract.schema.json"] = `${JSON.stringify(
  z.toJSONSchema(beaErrorEnvelopeSchema, { target: "draft-2020-12" }),
  null,
  2,
)}\n`;

process.stdout.write(JSON.stringify({ files }));
